    private readonly ModelDocumentOperations _documents=new();private readonly ModelComponentOperations _components=new();private readonly RigMath _rig=new();
    public void update_model(Node3D owner,Variant source)
    {
        var actor=Actor(owner);var values=actor.Get("values").AsGodotDictionary();string componentId=Get(values,"model_component_id","").AsString(),key=resource_identity(source)+":"+componentId;if(key==owner.Get("loaded_model_path").AsString()){bind_model_skin(owner);return;}owner.Set("loaded_model_path",key);var content=Content(owner)!;foreach(var child in content.GetChildren())child.Free();Resource? resource=source.VariantType==Variant.Type.Object?source.AsGodotObject() as Resource:null;string path=source.ToString(),loadPath=godot_resource_path(path);if(resource==null&&loadPath.Length>0&&ResourceLoader.Exists(loadPath))resource=_links.resolved_resource(loadPath);bool document=ActorDataOperations.ScriptIs(resource,"res://Workspaces/ModelWorkspace/model_document.gd");Resource? item=document?_documents.component(resource!,componentId):path==Get(values,"model_component_source","").ToString()?Get(values,"model_component_data").As<Resource>():null;if(item!=null&&document&&values.ContainsKey("model_rig_bind_signature")){var sourceRig=_documents.component(resource!,item.Get("skeleton_id").AsString());if(sourceRig==null||_rig.bind_signature(sourceRig.Get("bones").AsGodotArray())!=values["model_rig_bind_signature"].AsInt64())item=Get(values,"model_component_data").As<Resource>();}Node3D? instance=null;
        if(item!=null||document&&componentId.Length>0&&path==Get(values,"model_component_source","").ToString()){if(item!=null&&item.Get("growth").AsGodotObject()!=null){var visual=GD.Load<GDScript>("res://Workspaces/ModelWorkspace/growth/surface_growth_instance.gd").New().As<MeshInstance3D>();_growthInstances.configure(visual,item,true);visual.Visible=!Get(values,"model_component_hidden",false).AsBool();instance=visual;}else if(item!=null&&item.Get("mesh").AsGodotObject()!=null){var visual=new_mesh_instance();var skinMesh=item.Get("skin_mesh").As<Mesh>();var binding=item.Get("binding").As<Resource>();visual.Mesh=skinMesh??(binding!=null?binding.Get("source_mesh").As<Mesh>():_components.render_mesh(item,default));visual.Skin=item.Get("skin").As<Skin>();var materials=item.Get("surface_materials").AsGodotArray();for(int i=0;i<Math.Min(materials.Count,visual.Mesh.GetSurfaceCount());i++)visual.SetSurfaceOverrideMaterial(i,skinMesh==null&&binding==null?visual.Mesh.SurfaceGetMaterial(i):materials[i].As<Material>());visual.Visible=!Get(values,"model_component_hidden",false).AsBool();instance=visual;}}
        else if(resource is PackedScene packed)instance=packed.Instantiate() as Node3D;else if(document)instance=_documents.instantiate_model(resource!);else if(resource is Mesh mesh){var visual=new_mesh_instance();visual.Mesh=mesh;instance=visual;}else if(path.Length>0&&path.GetExtension().ToLowerInvariant() is "glb" or "gltf"){var gltf=new GltfDocument();var state=new GltfState();if(gltf.AppendFromFile(path,state)==Error.Ok)instance=gltf.GenerateScene(state) as Node3D;}if(instance!=null){content.AddChild(instance);bind_model_skin(owner);}
