    public void bind_model_skin(Node3D owner)
    {
        var values=Actor(owner).Get("values").AsGodotDictionary();if(values.ContainsKey("model_rigid_bone"))return;string id=Get(values,"model_skeleton_actor","").AsString();if(id.Length==0||!owner.IsInsideTree())return;foreach(var rig in owner.GetTree().GetNodesInGroup("actor_skeleton_rigs")){if(rig.Get("actor").As<Resource>().Get("id").AsString()!=id)continue;var skeleton=rig.Get("skeleton").As<Skeleton3D>();foreach(var node in Content(owner)!.GetChildren()){if(Growth(node)){node.Set("growth_skeleton",skeleton);_growthInstances.update_growth((MeshInstance3D)node);continue;}if(node is MeshInstance3D mesh){mesh.Skeleton=mesh.GetPathTo(skeleton);if(Get(values,"model_skin_in_rig_space",false).AsBool())mesh.GlobalTransform=skeleton.GlobalTransform;}}return;}
    }
    public void apply_rig_attachment(Node3D owner)
    {
        var content=Content(owner);if(GodotObject.IsInstanceValid(content))foreach(var node in content!.GetChildren())if(Growth(node)){bind_model_skin(owner);_growthInstances.update_growth((MeshInstance3D)node);}var values=Actor(owner).Get("values").AsGodotDictionary();if(!values.ContainsKey("model_rigid_bone")){if(Get(values,"model_skin_in_rig_space",false).AsBool())bind_model_skin(owner);return;}foreach(var rig in owner.GetTree().GetNodesInGroup("actor_skeleton_rigs")){if(rig.Get("actor").As<Resource>().Get("id").AsString()!=Get(values,"model_skeleton_actor","").AsString())continue;var skeleton=rig.Get("skeleton").As<Skeleton3D>();int index=values["model_rigid_bone"].AsInt32();if(index<0||index>=skeleton.GetBoneCount())return;var delta=skeleton.GlobalTransform*skeleton.GetBoneGlobalPose(index)*values["model_rigid_rest_inverse"].AsTransform3D()*skeleton.GlobalTransform.AffineInverse();var spatial=(Node3D)content!;var moved=delta*spatial.GlobalTransform;spatial.GlobalTransform=moved;owner.Get("parenting_anchor").As<Node3D>().GlobalTransform=moved;return;}
    }
    public void refresh_saved_model(Node3D owner,string path){var actor=owner.Get("actor").As<Resource>();if(actor==null||actor.Get("type_id").AsString()!="basic_mesh")return;string source=Get(actor.Get("values").AsGodotDictionary(),"mesh_path","").ToString();if(ProjectSettings.GlobalizePath(source).Replace('\\','/').SimplifyPath()==ProjectSettings.GlobalizePath(path).Replace('\\','/').SimplifyPath()){owner.Set("loaded_model_path","");update_model(owner,source);}}
    public void refresh_model_binding(Node3D owner,string path){var actor=Actor(owner);if(_links.refresh(actor,path))evaluate_transform(owner,_animation.sampled_values(actor,actor.Get("animation_time").AsDouble()));}
